\section{Introduction}

Let $[n]=\{1,\dots,n\}$ be a finite ground set and let
$\mathcal{F}\subseteq 2^{[n]}$ be a family of subsets. A set $S\subseteq[n]$ is
\emph{shattered} by $\mathcal{F}$ if every $T\subseteq S$ arises as a trace
$s\cap S$ for some $s\in\mathcal{F}$. The \emph{VC dimension} $\vc(\mathcal{F})$ is
the maximum cardinality of a shattered set. This single integer controls uniform
convergence of empirical averages, sample complexity of PAC learning, and the
combinatorial complexity of range spaces in computational geometry.

The foundational extremal result is the \emph{Sauer--Shelah lemma}: if
$\vc(\mathcal{F})\le d$, then
\[
  |\mathcal{F}|\;\le\;\sum_{k=0}^{d}\binom{n}{k}.
\]
The bound is tight without further constraints. The questions sharpen dramatically
once one imposes \emph{uniformity}: every member of $\mathcal{F}$ has the same
cardinality.

\begin{problem}
Fix $d\ge 2$ and $n\ge 2d+2$. Let $M_d(n)$ be the maximum cardinality of a
$(d{+}1)$-uniform family $\mathcal{A}\subseteq\binom{[n]}{d+1}$ with
$\vc(\mathcal{A})\le d$. Determine $M_d(n)$ and the extremal families.
\end{problem}

\begin{conjecture}[layered-star formula]
\[
  M_d(n)\;=\;\max_{0\le k\le\lfloor d/2\rfloor}\;
  \sum_{i=0}^{k}\binom{n-2i-1}{\,d-2i\,},
\]
attained by the layered-star construction of Section~\ref{sec:formula}.
\end{conjecture}

This refines the Ahlswede--Khachatrian bound and predicts the exact extremal
families. In this paper we develop the counting machinery and verify the
construction (lower-bound) side, isolating the matching upper bound as the central
open problem.

\section{A binomial-coefficient toolkit}

Throughout, $\binom{n}{k}$ denotes the binomial coefficient (zero when $k>n$).

\begin{lemma}[central entry is maximal, \texttt{choose\_le\_middle}]
For all $n,k$, $\displaystyle\binom{n}{k}\le\binom{n}{\lfloor n/2\rfloor}.$
\end{lemma}
\begin{proof}[Proof sketch]
The row $k\mapsto\binom{n}{k}$ is symmetric about $n/2$ and unimodal: the ratio
$\binom{n}{k+1}/\binom{n}{k}=(n-k)/(k+1)$ exceeds $1$ for $k<\lfloor n/2\rfloor$
and drops below $1$ afterward, so the maximum is the central entry.
\end{proof}

\begin{lemma}[monotonicity in the upper index, \texttt{choose\_mono\_n}]
If $n\le m$ then $\binom{n}{k}\le\binom{m}{k}$ for every $k$.
\end{lemma}
\begin{proof}[Proof sketch]
$\binom{n}{k}$ counts $k$-subsets of $[n]$; enlarging the ground set only adds
such subsets.
\end{proof}

\begin{lemma}[full row sum, \texttt{sum\_range\_choose\_eq}]
$\displaystyle\sum_{k=0}^{n}\binom{n}{k}=2^{n}.$
\end{lemma}
\begin{proof}[Proof sketch]
Count all subsets of $[n]$ by size, or set $x=1$ in $(1+x)^n$.
\end{proof}

\begin{lemma}[truncated row is $\le 2^n$, \texttt{sum\_range\_choose\_le\_pow}]
If $d\le n$ then $\displaystyle\sum_{k=0}^{d}\binom{n}{k}\le 2^{n}.$
\end{lemma}
\begin{proof}[Proof sketch]
The truncated sum is a sub-sum of the full row of nonnegative terms, which equals
$2^n$.
\end{proof}

\section{The layered-star formula and its central-layer maximum}\label{sec:formula}

\begin{definition}[Sauer--Shelah sum]
$\displaystyle\layeredSum(n,d):=\sum_{k=0}^{d}\binom{n}{k}.$
\end{definition}

\begin{proposition}[boundary and monotonicity]
\begin{enumerate}
\item \textup{(\texttt{layeredSum\_zero})} $\layeredSum(n,0)=1$.
\item \textup{(\texttt{layeredSum\_mono\_d})} If $d_1\le d_2$ then
  $\layeredSum(n,d_1)\le\layeredSum(n,d_2)$.
\item \textup{(\texttt{layeredSum\_mono\_n})} If $n_1\le n_2$ then
  $\layeredSum(n_1,d)\le\layeredSum(n_2,d)$.
\item \textup{(\texttt{layeredSum\_le\_pow})} If $d\le n$ then
  $\layeredSum(n,d)\le 2^{n}$.
\end{enumerate}
\end{proposition}
\begin{proof}[Proof sketch]
(1) only the $k=0$ term survives, equal to $1$. (2) the larger sum ranges over a
superset of nonnegative summands. (3) termwise by monotonicity in $n$. (4) by the
truncated-row lemma.
\end{proof}

\begin{definition}[star-layer profile]
$\starLayer(d,k):=\binom{d}{k}.$
\end{definition}

\begin{proposition}[central layer maximizes, \texttt{starLayer\_max}]
For all $k$, $\starLayer(d,k)\le\starLayer(d,\lfloor d/2\rfloor)$.
\end{proposition}
\begin{proof}[Proof sketch]
Immediate from central maximality applied to row $d$.
\end{proof}

\begin{definition}[central-layer size]
$\displaystyle\Mformula(n,d):=\binom{n}{\lfloor d/2\rfloor}.$
\end{definition}

\begin{proposition}[central layer is one summand, \texttt{Mformula\_le\_layeredSum}]
$\Mformula(n,d)\le\layeredSum(n,d)$.
\end{proposition}
\begin{proof}[Proof sketch]
$\binom{n}{\lfloor d/2\rfloor}$ is the single $k=\lfloor d/2\rfloor$ term (with
$\lfloor d/2\rfloor\le d$) of a nonnegative sum.
\end{proof}

\begin{proposition}[monotone in $n$, \texttt{Mformula\_mono\_n}]
If $n_1\le n_2$ then $\Mformula(n_1,d)\le\Mformula(n_2,d)$.
\end{proposition}
\begin{proof}[Proof sketch]
Monotonicity in $n$ with $k=\lfloor d/2\rfloor$.
\end{proof}

\section{A verified uniform layered-star family}

\begin{definition}[shattering]
$\mathcal{F}$ \emph{shatters} $S$ if
$\forall\,T\subseteq S,\ \exists\, s\in\mathcal{F},\ s\cap S=T.$
\end{definition}

\begin{definition}[bounded VC dimension]
$\VCdimLe(\mathcal{F},d)$ holds if every shattered $S$ satisfies $|S|\le d$.
\end{definition}

\begin{definition}[uniform layered-star family]
$\displaystyle\uniformStarFamily(n,d):=\binom{[n]}{\lfloor d/2\rfloor},$ the family
of all $\lfloor d/2\rfloor$-element subsets of $[n]$.
\end{definition}

\begin{theorem}[size, \texttt{uniformStarFamily\_card}]
$\bigl|\uniformStarFamily(n,d)\bigr|=\Mformula(n,d)=\binom{n}{\lfloor d/2\rfloor}.$
\end{theorem}
\begin{proof}[Proof sketch]
The number of $r$-subsets of an $n$-set is $\binom{n}{r}$ with
$r=\lfloor d/2\rfloor$.
\end{proof}

\begin{theorem}[uniformity, \texttt{uniformStarFamily\_uniform}]
Every $s\in\uniformStarFamily(n,d)$ has $|s|=\lfloor d/2\rfloor$.
\end{theorem}
\begin{proof}[Proof sketch]
Membership is defined as being an $\lfloor d/2\rfloor$-subset.
\end{proof}

\begin{theorem}[VC bound, \texttt{uniformStarFamily\_vcDimLe}]
$\VCdimLe\bigl(\uniformStarFamily(n,d),\,d\bigr).$
\end{theorem}
\begin{proof}[Proof sketch (the full-pattern argument)]
Suppose $S$ is shattered. Apply shattering to the maximal dichotomy $T=S$: there
exists $s$ in the family with $s\cap S=S$, forcing $S\subseteq s$, hence
$|S|\le|s|$. By uniformity $|s|=\lfloor d/2\rfloor$, so
$|S|\le\lfloor d/2\rfloor\le d$.
\end{proof}

\begin{theorem}[existence, \texttt{exists\_uniform\_VC\_family}]
For every $n,d$ there exists a uniform family $\mathcal{F}$ on $[n]$ with
$\VCdimLe(\mathcal{F},d)$ and $|\mathcal{F}|=\binom{n}{\lfloor d/2\rfloor}$.
\end{theorem}
\begin{proof}[Proof sketch]
Take $\mathcal{F}=\uniformStarFamily(n,d)$ and combine the three preceding
theorems.
\end{proof}

\begin{remark}[sharpness of the local bound]
The inequality $|S|\le\lfloor d/2\rfloor$ is exactly the member-size constraint, so
the construction uses its entire budget on the central layer. This local
sharpness is the seed the compression program must propagate globally.
\end{remark}

\section{Discussion and open problems}

The results verified here are the construction half of the program. What remains is
the matching upper bound.

\begin{problem}[matching upper bound]
For $d\ge2$ and $n\ge2d+2$, every $(d{+}1)$-uniform $\mathcal{A}$ on $[n]$ with
$\vc(\mathcal{A})\le d$ satisfies $|\mathcal{A}|\le M_d(n)$.
\end{problem}

The natural attack is compression/shifting: the verified one-point saving is a
local seed that a down-compression argument should propagate to the whole family,
paralleling Pajor's proof of Sauer--Shelah. Further conjectures: an admissibility
window ($i$-th layer admissible iff $n\ge2d+2$); value-vs-extremiser
(monotonicity collapses the numeric maximum to the top index, so the content is
which family is admissible); and stability/uniqueness (for $n\ge2d+3$ every
maximizer is isomorphic to the top layered star).

\section{Conclusion}

Starting from the definition of VC dimension and the Sauer--Shelah ceiling, we
isolated the binomial phenomena that make the layered-star construction natural and
verified an explicit uniform family realizing the central-layer size
$\binom{n}{\lfloor d/2\rfloor}$ with VC dimension at most $d$. The construction side
of the conjecture is thereby placed on rigorous footing, and the matching upper
bound is cleanly framed as the central open problem, with compression as the most
promising route.

